{"content": "# -*- coding: utf-8 -*-
"""主核算管线: 分类 -> 火电热力(POWER)目标核算 -> 输出5个文件"""
import pandas as pd
import numpy as np
import json
import os
import math
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from inventory_lib import (POLLUTANTS, TABLE_C1_AR, SR_BOTTOM, TABLE_C2, TABLE_C3,
                           TABLE_D1, D1_KEYS, NOX_CAP_RULE, FUEL_MAP, NO_FACTOR_FUELS,
                           GAS_FUELS, LIQUID_FUELS, COAL_FUELS, TECH_MAP_COAL,
                           FACILITY_PRIMARY, norm_tech_name, a1_vector,
                           classify_industry, load_b102, load_ctrl, nonempty,
                           INPUTS, OUTPUTS)

def fmt_num(x):
    if x is None:
        return ""
    x = float(x)
    if abs(x) < 0.5e-6:
        return "0"
    return format(round(x, 6), ".6f").rstrip("0").rstrip(".")

# ----------------------------------------------------------------------------
# 组件构建
# ----------------------------------------------------------------------------
def build_component(row, ftype, value, unit, sulfur, ash, capacity, dev_kind):
    comp = {
        "fuel_type": str(ftype).strip(),
        "value": float(value),
        "unit": str(unit).strip() if pd.notna(unit) else "",
    }
    ftype_s = comp["fuel_type"]
    comp["fuel_category"] = FUEL_MAP.get(ftype_s)
    comp["ef_unit"] = "g/m3" if comp["unit"] == "万立方米" else "g/kg"

    tech = None
    gt_assumption = False
    if dev_kind == "POWER_DEV":
        dev_type = str(row["电站锅炉/燃气轮机类型"]).strip() if pd.notna(row["电站锅炉/燃气轮机类型"]) else ""
        burn = str(row["电站锅炉燃烧方式"]).strip() if pd.notna(row["电站锅炉燃烧方式"]) else ""
        if ftype_s in GAS_FUELS:
            if dev_type == "燃气轮机":
                tech = "燃气锅炉"; gt_assumption = True
            elif dev_type in ("余热利用锅炉", "其他锅炉"):
                tech = None
            else:
                tech = "燃气锅炉"
        elif ftype_s in LIQUID_FUELS:
            if dev_type in ("余热利用锅炉", "其他锅炉"):
                tech = None
            else:
                tech = "燃油锅炉"
        elif ftype_s in COAL_FUELS:
            tech = TECH_MAP_COAL.get(burn)
    else:
        burn = str(row["工业锅炉燃烧方式"]).strip() if pd.notna(row["工业锅炉燃烧方式"]) else ""
        if ftype_s in GAS_FUELS:
            tech = "燃气锅炉"
        elif ftype_s in LIQUID_FUELS:
            tech = "燃油锅炉"
        elif ftype_s in COAL_FUELS:
            tech = TECH_MAP_COAL.get(burn)
    comp["device_tech"] = tech
    comp["gt_assumption"] = gt_assumption
    comp["sulfur_pct"] = float(sulfur) if pd.notna(sulfur) else None
    comp["ash_pct"] = float(ash) if pd.notna(ash) else None
    comp["capacity_mw"] = float(cap) if pd.notna(cap := capacity) else None
    return comp

def build_components(row, dev_kind):
    comps = []
    f1_type = row["燃料一类型"]
    if pd.notna(f1_type):
        val = row["燃料一消耗量"]
        if pd.notna(val) and float(val) > 0:
            comps.append(("F1", build_component(row, f1_type, val, row["燃料一消耗量单位"],
                                                row["燃料一平均收到基含硫量"], row["燃料一平均收到基灰分（%）"],
                                                row["对应机组装机容量（万千瓦）"], dev_kind)))
    f2_type = row["燃料二类型"]
    if pd.notna(f2_type):
        val = row["燃料二消耗量"]
        if pd.notna(val) and float(val) > 0:
            comps.append(("F2", build_component(row, f2_type, val, row["燃料二消耗量单位"],
                                                row["燃料二平均收到基含硫量"], row["燃料二平均收到基灰分（%）"],
                                                row["对应机组装机容量（万千瓦）"], dev_kind)))
    oth = row["其他燃料消耗总量（吨标准煤）"]
    if pd.notna(oth) and float(oth) > 0:
        comps.append(("OTH", build_component(row, "其他燃料", oth, "吨标准煤", None, None,
                                             row["对应机组装机容量（万千瓦）"], dev_kind)))
    return comps

# ----------------------------------------------------------------------------
# 每组分每污染物 EF: 返回 (value, mode, unit, reason) 或 (None, "missing", unit, reason)
# ----------------------------------------------------------------------------
def component_ef(comp, sector):
    ftype = comp["fuel_type"]
    if ftype in NO_FACTOR_FUELS or comp["fuel_category"] is None:
        r = "EF_MISSING_OTHER_FUEL" if ftype == "其他燃料" else "EF_MISSING_FUEL"
        return {p: (None, "missing", comp["ef_unit"], r) for p in POLLUTANTS}
    if comp["device_tech"] is None:
        return {p: (None, "missing", comp["ef_unit"], "EF_MISSING_TECH") for p in POLLUTANTS}

    fuel_cat = comp["fuel_category"]
    tech = comp["device_tech"]
    key = (fuel_cat, tech)
    if key not in TABLE_D1[sector]:
        key = (fuel_cat, "不分技术")
    if key not in TABLE_D1[sector]:
        if comp["gt_assumption"]:
            key = (fuel_cat, "燃气锅炉")
        else:
            return {p: (None, "missing", comp["ef_unit"], "EF_MISSING_TECH") for p in POLLUTANTS}
    if key not in TABLE_D1[sector]:
        return {p: (None, "missing", comp["ef_unit"], "EF_MISSING_TECH") for p in POLLUTANTS}
    d1 = dict(zip(D1_KEYS, TABLE_D1[sector][key]))

    ef = {}
    for p in POLLUTANTS:
        if p == "NH3":
            ef[p] = (0.0, "zero_standard", comp["ef_unit"], "NH3_EF_ZERO_STANDARD")
            continue
        v = d1[p]
        if p in ("SO2", "PM2.5", "PM10", "BC", "OC") and v == "MB":
            if p == "SO2":
                s = comp["sulfur_pct"]
                if s is None:
                    ef[p] = (None, "missing", "g/kg", "COAL_QUALITY_MISSING")
                else:
                    ef[p] = (2 * s * (1 - SR_BOTTOM) * 10, "material_balance", "g/kg", "SO2_MB")
            else:
                ash = comp["ash_pct"]
                if ash is None:
                    ef[p] = (None, "missing", "g/kg", "COAL_QUALITY_MISSING")
                else:
                    ar = TABLE_C1_AR[sector].get(tech, 0.85)
                    f25, f10 = TABLE_C2[sector][tech]
                    base25 = 10 * ash * (1 - ar) * f25
                    if p == "PM2.5":
                        ef[p] = (base25, "material_balance", "g/kg", "PM_MB")
                    elif p == "PM10":
                        ef[p] = (10 * ash * (1 - ar) * f10, "material_balance", "g/kg", "PM_MB")
                    else:
                        fbc, foc = TABLE_C3[sector][tech]
                        ef[p] = (base25 * (fbc if p == "BC" else foc), "material_balance", "g/kg", "PM_MB")
        elif p == "NOx" and v == "CAP":
            cap = comp["capacity_mw"]
            if cap is None:
                ef[p] = (None, "missing", "g/kg", "NOX_CAPACITY_MISSING")
            else:
                ef[p] = (next(vv for lim, vv in NOX_CAP_RULE if cap <= lim), "capacity_rule", "g/kg", "NOX_CAP")
        elif v is None:
            ef[p] = (None, "missing", comp["ef_unit"], "EF_MISSING_TECH")
        else:
            ef[p] = (float(v), "table_D1", comp["ef_unit"], "D1")
    return ef

def generation_from_ef(comp, ef_value):
    if comp["unit"] == "万立方米":
        return comp["value"] * 1e4 * ef_value / 1e6
    return comp["value"] * ef_value / 1e3

# ----------------------------------------------------------------------------
# 控制效率 (百分比)
# ----------------------------------------------------------------------------
def control_efficiency(row, ctrl_df, dev_kind):
    port = "DZGL" if dev_kind == "POWER_DEV" else "GYGL"
    facs = ctrl_df[(ctrl_df["统一社会信用代码"] == row["统一社会信用代码"]) &
                   (ctrl_df["对应的排放口代码"] == port)]
    eta = {k: 0.0 for k in ["SO2", "NOx", "VOC", "PM2.5", "PM2.5_10", "BC", "OC"]}
    used = {k: [] for k in eta}
    flags = set()
    for _, f in facs.iterrows():
        name = str(f["废气治理设施名称"]).strip() if pd.notna(f["废气治理设施名称"]) else ""
        primary = FACILITY_PRIMARY.get(name, [])
        tech = norm_tech_name(f["处理工艺名称"])
        vec = a1_vector(tech) if tech else {k: 0.0 for k in eta}
        declared = f["去除效率（%）"]
        if pd.notna(declared):
            try:
                d = float(declared)
            except Exception:
                d = None
            if d is not None and 0 <= d <= 100:
                for p in primary:
                    vec[p] = d
                if "PM2.5" in primary:
                    vec["PM2.5_10"] = d
            else:
                flags.add("CONTROL_EFF_INVALID")
        elif tech is None:
            flags.add("CONTROL_EFF_UNKNOWN")
        for k in eta:
            if vec[k] > eta[k]:
                eta[k] = vec[k]
                used[k] = [(name, tech)]
            elif vec[k] > 0 and vec[k] == eta[k]:
                used[k].append((name, tech))
    # 低氮燃烧 (设备级)
    low_col = "是否采用低氮燃烧技术" if dev_kind == "POWER_DEV" else "是否采用低氮燃烧技术.1"
    low_nox = row[low_col]
    if pd.notna(low_nox) and str(low_nox).strip() == "是":
        if eta["NOx"] < 22:
            eta["NOx"] = 22
        scr = any(t and "选择性催化还原法" in t for _, t in used["NOx"])
        sncr = any(t and "选择性非催化还原法" in t for _, t in used["NOx"])
        if scr and eta["NOx"] < 64:
            eta["NOx"] = 64
        elif sncr and eta["NOx"] < 52:
            eta["NOx"] = 52
    return eta, used, flags

# ----------------------------------------------------------------------------
# 主流程
# ----------------------------------------------------------------------------
def main():
    df = load_b102()
    ctrl = load_ctrl()
    print("B102 rows:", len(df), "| ctrl rows:", len(ctrl))

    df["decided_target"] = df["行业类别代码"].map(classify_industry)
    df["dev_kind"] = np.where(nonempty(df["电站锅炉/燃气轮机编号"]), "POWER_DEV", "IND_DEV")
    print(df["decided_target"].value_counts().to_string())

    decisions, dispositions, items = [], [], []
    exceptions = {}

    power_df = df[df["decided_target"] == "POWER"]
    print("POWER sources:", len(power_df))

    for _, row in power_df.iterrows():
        sid = row["source_id"]
        sector = "电力生产" if str(row["行业类别代码"]).strip() in {"4411", "4412", "4417"} else "热力生产和供应"
        comps = build_components(row, row["dev_kind"])
        eta, used, cflags = control_efficiency(row, ctrl, row["dev_kind"])
        gt_flag = any(c["gt_assumption"] for _, c in comps)

        for p in POLLUTANTS:
            act_rec, par_rec, ctl_rec = [], [], []
            gen_total, emi_total = 0.0, 0.0
            all_ok = True
            missing = set()
            for cid, comp in comps:
                act_rec.append({"component_id": cid, "value": comp["value"], "unit": comp["unit"]})
                efres = component_ef(comp, sector)
                item = efres[p]
                if item[0] is None:
                    par_rec.append({"component_id": cid, "parameter_id": "EF_" + p,
                                    "mode": "missing", "value": None, "unit": item[2]})
                    missing.add(item[3])
                    all_ok = False
                    gen_c = None
                else:
                    efv, mode, unit, _ = item
                    par_rec.append({"component_id": cid, "parameter_id": "EF_" + p,
                                    "mode": mode, "value": efv, "unit": unit})
                    gen_c = generation_from_ef(comp, efv)
                    gen_total += gen_c
                if p == "PM10":
                    ctl_rec.append({"component_id": cid,
                                    "method": "|".join(dict.fromkeys(m for m, _ in used["PM2.5"])) if used["PM2.5"] else "无治理",
                                    "efficiency": None,
                                    "fine_efficiency": eta["PM2.5"] / 100.0,
                                    "coarse_efficiency": eta["PM2.5_10"] / 100.0})
                else:
                    eff = eta.get(p, 0.0) / 100.0
                    ctl_rec.append({"component_id": cid,
                                    "method": "|".join(dict.fromkeys(m for m, _ in used.get(p, []))) if used.get(p) else "无治理",
                                    "efficiency": eff,
                                    "fine_efficiency": None,
                                    "coarse_efficiency": None})
            if not all_ok:
                status, reason = "information_insufficient", ";".join(sorted(missing))
                gen_total, emi_total = None, None
            else:
                # PM10 组分核算: 细组分(PM2.5)用fine效率, 粗组分(PM10-PM2.5)用coarse效率
                if p == "PM10":
                    gen_total, emi_total = 0.0, 0.0
                    for cid, comp in comps:
                        efres = component_ef(comp, sector)
                        ef25 = efres["PM2.5"]
                        ef10 = efres["PM10"]
                        g25 = generation_from_ef(comp, ef25[0])
                        g10 = generation_from_ef(comp, ef10[0])
                        gen_total += g10
                        emi_total += g25 * (1 - eta["PM2.5"] / 100.0) + (g10 - g25) * (1 - eta["PM2.5_10"] / 100.0)
                else:
                    emi_total = 0.0
                    for cid, comp in comps:
                        efres = component_ef(comp, sector)
                        item = efres[p]
                        gen_c = generation_from_ef(comp, item[0])
                        emi_total += gen_c * (1 - eta.get(p, 0.0) / 100.0)
                status = "calculated"
                reason = "OK"
                if cflags:
                    reason += ";" + ";".join(sorted(cflags))
                if gt_flag:
                    reason += ";GT_AS_GAS_BOILER"
                if p == "NH3":
                    reason += ";NH3_EF_ZERO_STANDARD"
            if len(comps) == 0:
                status, reason = "information_insufficient", "NO_ACTIVITY_DATA"
                gen_total, emi_total = None, None

            std_ref = standard_ref(p, comps, sector)
            items.append({
                "source_id": sid, "target": "POWER", "pollutant": p, "status": status,
                "method": method_for(p, comps),
                "activity_record_json": json.dumps(act_rec, ensure_ascii=False, separators=(",", ":")),
                "parameter_record_json": json.dumps(par_rec, ensure_ascii=False, separators=(",", ":")),
                "control_record_json": json.dumps(ctl_rec, ensure_ascii=False, separators=(",", ":")),
                "generation_t": fmt_num(gen_total) if gen_total is not None else "",
                "emission_t": fmt_num(emi_total) if emi_total is not None else "",
                "standard_reference": std_ref,
                "reason_code": reason,
            })
            if status != "calculated":
                for r in (reason.split(";") if reason else ["NO_ACTIVITY_DATA"]):
                    exceptions.setdefault(r, {"sources": set(), "pollutants": set()})
                    exceptions[r]["sources"].add(sid)
                    exceptions[r]["pollutants"].add(p)
            elif "CONTROL_EFF_UNKNOWN" in reason:
                exceptions.setdefault("CONTROL_EFF_UNKNOWN", {"sources": set(), "pollutants": set()})
                exceptions["CONTROL_EFF_UNKNOWN"]["sources"].add(sid)
                exceptions["CONTROL_EFF_UNKNOWN"]["pollutants"].add(p)

    # ---- 非目标源 ----
    other_df = df[df["decided_target"] != "POWER"]
    for _, row in other_df.iterrows():
        sid = row["source_id"]
        dt = row["decided_target"]
        reason = "NOT_TARGET_BOILER" if dt == "BOILER" else "NOT_TARGET_OUT_OF_SCOPE"
        for p in POLLUTANTS:
            items.append({
                "source_id": sid, "target": "POWER", "pollutant": p, "status": "not_involved",
                "method": "",
                "activity_record_json": "[]",
                "parameter_record_json": "[]",
                "control_record_json": "[]",
                "generation_t": "",
                "emission_t": "",
                "standard_reference": "",
                "reason_code": reason,
            })

    # ---- 决策与处置 ----
    for _, row in df.iterrows():
        sid = row["source_id"]
        dt = row["decided_target"]
        ind = str(row["行业类别代码"]).strip()
        if dt == "POWER":
            disp, rcode = "target_included", "IND_" + ind + "_POWER_SCOPE"
        elif dt == "BOILER":
            disp, rcode = "decided_industrial_boiler", "IND_" + ind + "_INDUSTRIAL_SCOPE"
        else:
            disp, rcode = "out_of_scope", "IND_" + ind + "_NOT_IN_STANDARD_SCOPE"
        decisions.append({"source_id": sid, "requested_target": "POWER", "decided_target": dt,
                          "disposition": disp, "reason_code": rcode})
        dispositions.append({"source_id": sid, "target": "POWER", "disposition": disp, "reason_code": rcode})

    # ---- 输出 ----
    pd.DataFrame(decisions).to_csv(os.path.join(OUTPUTS, "source_decisions.csv"), index=False, encoding="utf-8-sig")
    items_df = pd.DataFrame(items)
    items_df.to_csv(os.path.join(OUTPUTS, "generic_inventory_items.csv"), index=False, encoding="utf-8-sig")
    pd.DataFrame(dispositions).to_csv(os.path.join(OUTPUTS, "generic_source_disposition.csv"), index=False, encoding="utf-8-sig")

    exc_meta = {
        "EF_MISSING_FUEL": ("生物质/城市生活垃圾/工业废料燃料无表D.1产生系数", "补充生物质/垃圾发电产生系数(实测或系数库)后重算"),
        "EF_MISSING_OTHER_FUEL": ("其他燃料(吨标准煤)无表D.1产生系数", "明确其他燃料构成并补充产生系数"),
        "EF_MISSING_TECH": ("设备技术(余热利用锅炉/其他锅炉/燃烧方式)无法匹配表D.1", "补充设备技术信息或采用实测系数"),
        "NOX_CAPACITY_MISSING": ("燃煤机组装机容量缺失, NOx系数无法按容量档选取", "补充对应机组装机容量后重算NOx"),
        "COAL_QUALITY_MISSING": ("燃煤含硫量或灰分缺失, 物料衡算无法进行", "补充燃料煤质数据(收到基硫分/灰分)"),
        "CONTROL_EFF_UNKNOWN": ("治理设施去除效率缺失且工艺无法匹配表A.1, η按0计", "补充治理设施去除效率或投运率"),
        "NO_ACTIVITY_DATA": ("源无有效燃料消耗量数据", "核实燃料消耗量填报"),
    }
    exc_rows = []
    for i, (rc, info) in enumerate(sorted(exceptions.items()), 1):
        root, action = exc_meta.get(rc, (rc, "需人工核查"))
        exc_rows.append({
            "exception_id": "EXC-%02d" % i,
            "source_id": ",".join(sorted(info["sources"])),
            "pollutant": ",".join(sorted(info["pollutants"])),
            "root_cause": root,
            "action_required": action,
        })
    pd.DataFrame(exc_rows).to_csv(os.path.join(OUTPUTS, "generic_exception_list.csv"), index=False, encoding="utf-8-sig")

    summary = {
        "run_id": "C-75-POW-GEN-R1",
        "target": "POWER",
        "input_files": {
            "b102_device_fuel": os.path.join(INPUTS, "基102-2002_原始结构脱敏输入.xlsx"),
            "b101_control_facility": os.path.join(INPUTS, "基101-2002_原始结构脱敏输入.xlsx"),
            "b101_enterprise_master_shards": sorted(os.path.join(INPUTS, f) for f in os.listdir(INPUTS) if f.startswith("基101-2001")),
            "standard": os.path.join(INPUTS, "T_CSES_144-2024.pdf"),
            "identity_index": os.path.join(INPUTS, "source_identity_index.json"),
        },
        "candidate_sources_total": int(len(df)),
        "decided_counts": {k: int(v) for k, v in df["decided_target"].value_counts().to_dict().items()},
        "inventory_item_rows": int(len(items_df)),
        "item_status_counts": {k: int(v) for k, v in items_df["status"].value_counts().to_dict().items()},
        "calculated_items_by_pollutant": {
            k: int(v) for k, v in items_df[items_df["status"] == "calculated"].groupby("pollutant").size().to_dict().items()
        },
        "output_files": {
